begin
  dut : entity work.adder_w12 port map (a => s_a, b => s_b, cin => s_cin, sum => s_sum, cout => s_cout);
  
  process
    variable l : line;
    variable got : std_logic_vector(1 to 13);
    variable errors : natural := 0;
  begin
    for i in stim'range loop
      s_a <= stim(i)(1 to 12);
      s_b <= stim(i)(13 to 24);
      s_cin <= stim(i)(25);
      wait for 5 ns;
      got(1 to 12) := s_sum;
      got(13) := s_cout;
      for b in got'range loop
        if expv(i)(b) /= '-' and got(b) /= expv(i)(b) then
          errors := errors + 1;
          if errors <= 10 then
            report "MISMATCH vector " & integer'image(i) & " bit " & integer'image(b)
              & " expected " & std_logic'image(expv(i)(b))
              & " got " & std_logic'image(got(b)) severity warning;
          end if;
        end if;
      end loop;
    end loop;
    done <= true;
    assert errors = 0
      report integer'image(errors) & " output bit(s) differ from the golden vectors"
      severity error;
    if errors = 0 then report "GOLDEN_PASS" severity note; end if;
    wait;
  end process;
end architecture;
